if (N % 2 != 0) {
    throw std::invalid_argument("Number of intervals (N) must be even for Simpson's rule.");
}

double h = (b - a) / N;
double integral = f(a) + f(b);

for (int i = 1; i < N; i++) {
    double x = a + i * h;
    if (i % 2 == 0) {
        integral += 2 * f(x);
    } else {
        integral += 4 * f(x);
    }
}

integral *= h / 3.0;
return integral;

